"""Handlers for the notes list: save a note dated today, count saved notes."""

from __future__ import annotations

from typing import Any

from alpha_sdk import Context, InvalidValue


def add_note(ctx: Context, title: str) -> dict[str, Any]:
    """Save one note, dated today in the person's timezone."""
    text = (title or "").strip()
    if not text:
        raise InvalidValue("Write a few words before saving the note.")
    record = ctx.records.create(
        "notes", {"title": text, "noted_on": ctx.today().isoformat()}
    )
    return {"id": record.id, "revision": record.revision}


def count_notes(ctx: Context) -> dict[str, Any]:
    """How many notes are saved."""
    return {"count": len(ctx.records.all("notes"))}

