"""Candidate-authored tests (supplementary evidence only)."""

import unittest
from datetime import date

from alpha_sdk import InvalidValue

import notes_app.handlers as handlers


class FakeRecord:
    def __init__(self, record_id, values):
        self.id = record_id
        self.revision = 1
        self.values = values


class FakeRecords:
    def __init__(self):
        self.rows = []

    def create(self, collection, values, **kwargs):
        assert collection == "notes"
        record = FakeRecord(f"note-{len(self.rows) + 1}", dict(values))
        self.rows.append(record)
        return record

    def all(self, collection, **kwargs):
        assert collection == "notes"
        return list(self.rows)


class FakeContext:
    def __init__(self):
        self.records = FakeRecords()

    def today(self):
        return date(2026, 9, 26)


class AddNote(unittest.TestCase):
    def test_saves_the_note_with_today(self):
        ctx = FakeContext()
        out = handlers.add_note(ctx, title="Buy milk")

        self.assertEqual(out, {"id": "note-1", "revision": 1})
        self.assertEqual(
            ctx.records.rows[0].values, {"title": "Buy milk", "noted_on": "2026-09-26"}
        )

    def test_trims_surrounding_space(self):
        ctx = FakeContext()
        handlers.add_note(ctx, title="  Buy milk  ")

        self.assertEqual(ctx.records.rows[0].values["title"], "Buy milk")

    def test_refuses_a_blank_note(self):
        ctx = FakeContext()
        for blank in ("", "   "):
            with self.assertRaises(InvalidValue):
                handlers.add_note(ctx, title=blank)
        self.assertEqual(ctx.records.rows, [])


class CountNotes(unittest.TestCase):
    def test_counts_what_is_saved(self):
        ctx = FakeContext()
        self.assertEqual(handlers.count_notes(ctx), {"count": 0})

        handlers.add_note(ctx, title="Buy milk")
        self.assertEqual(handlers.count_notes(ctx), {"count": 1})


if __name__ == "__main__":
    unittest.main()

