function App() {
  const add = useAction("add_note");
  const counter = useAction("count_notes");
  const recent = useView<Note>("notes.recent", { limit: 50 });

  const countNow = () => {
    // A failed count leaves the card empty; it never blocks writing or reading notes.
    counter.run({}).catch(() => undefined);
  };

  useEffect(countNow, []);

  const output = counter.output as unknown as { count?: number } | null | undefined;
  const saved = typeof output?.count === "number" ? output.count : null;

  return (
    <Page title="Notes" description="Write a short note; it is saved with today's date.">
      <Section title="Write a note">
