          onSubmit={async (title) => {
            await add.run({ title });
            countNow();
          }}
        />
        <OperationStatus state={add.state} error={add.error} />
      </Section>
      <Section title="How many">
        <MetricCard label="Notes saved" value={saved} hint="Everything you have written down." />
      </Section>
      <Section title="Latest notes">
        <RecordTable<RecordRow<Note>>
