// Notes: one field at the top to write a note, how many are saved, and the latest ones.
import { StrictMode, useEffect, useState } from "react";
import { createRoot } from "react-dom/client";
import "@alpha/ui-kit/styles.css";
import {
  AlphaApp,
  Button,
  Form,
  MetricCard,
  OperationStatus,
  Page,
  RecordTable,
  Section,
  TextField,
  formatDay,
  useAction,
  useView,
  type RecordRow,
} from "@alpha/ui-kit";

type Note = { title: string; noted_on: string };

function App() {
  const add = useAction("add_note");
  const counter = useAction("count_notes");
  const recent = useView<Note>("notes.recent", { limit: 50 });
  const [text, setText] = useState("");
  const [blank, setBlank] = useState(false);

  const countNow = () => {
    // A failed count leaves the card empty; it never blocks writing or reading notes.
    counter.run({}).catch(() => undefined);
  };

  useEffect(countNow, []);

  const output = counter.output as unknown as { count?: number } | null | undefined;
  const saved = typeof output?.count === "number" ? output.count : null;

  const submit = async () => {
    const title = text.trim();
    if (!title) {
      setBlank(true);
      return;
    }
    setBlank(false);
    try {
      await add.run({ title });
      setText("");
      countNow();
    } catch {
      // The status below explains; keep what was typed so it can be sent again.
    }
  };

  return (
    <Page title="Notes" description="Write a short note; it is saved with today's date.">
      <Section title="Write a note">
        <Form label="Write a note" onSubmit={submit}>
          <TextField
            label="Note"
            value={text}
            onChange={(next: any) => {
              const value = typeof next === "string" ? next : (next?.target?.value ?? "");
              setText(value);
              if (value.trim()) setBlank(false);
            }}
            hint="A few words are enough. Press Enter to save it."
            error={blank ? "Write a few words before saving." : undefined}
          />
          <Button type="submit" variant="primary" busy={add.state === "saving"} busyLabel="Saving…">
            Add
          </Button>
          <OperationStatus state={add.state} error={add.error} />
        </Form>
      </Section>
      <Section title="How many">
        <MetricCard label="Saved so far" value={saved} hint="Everything you have written down." />
      </Section>
      <Section title="Latest notes">
        <RecordTable<RecordRow<Note>>
          caption="Your latest notes"
          columns={[
            { id: "title", header: "What you wrote", cell: (r) => r.values.title },
            { id: "day", header: "Day", cell: (r) => formatDay(r.values.noted_on) },
          ]}
          rows={recent.records}
          getRowId={(r) => r.id}
          loading={recent.loading}
          error={recent.error}
          onRetry={recent.refresh}
          empty={{ title: "Nothing written yet", message: "Write the first one above." }}
        />
      </Section>
    </Page>
  );
}

createRoot(document.getElementById("root")!).render(
  <StrictMode>
    <AlphaApp>
      <App />
    </AlphaApp>
  </StrictMode>,
);
